import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        In in = new In();
        int n = in.nextInt(), m = in.nextInt();
        long[] houses = new long[n], stores = new long[m];
        for (int i = 0; i < n; i++) houses[i] = in.nextLong();
        for (int i = 0; i < m; i++) stores[i] = in.nextLong();
        Arrays.sort(stores);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long h = houses[i];
            int lo = 0, hi = m;
            while (lo < hi) { // first store >= h
                int mid = (lo + hi) >>> 1;
                if (stores[mid] < h) lo = mid + 1; else hi = mid;
            }
            long best = -1;
            if (lo < m) best = stores[lo];
            if (lo > 0) {
                long c = stores[lo - 1];
                if (best < 0 || Math.abs(c - h) < Math.abs(best - h) || (Math.abs(c - h) == Math.abs(best - h) && c < best)) best = c;
            }
            if (i > 0) sb.append(' ');
            sb.append(best);
        }
        System.out.println(sb);
    }

    static final class In {
        private final InputStream is = System.in;
        private final byte[] buf = new byte[1 << 16];
        private int len, ptr;
        private int read() throws IOException {
            if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
            return buf[ptr++];
        }
        long nextLong() throws IOException {
            int c = read();
            while (c != -1 && c <= ' ') c = read();
            boolean neg = c == '-';
            if (neg) c = read();
            long r = 0;
            while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
            return neg ? -r : r;
        }
        int nextInt() throws IOException { return (int) nextLong(); }
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

var sc = bufio.NewScanner(os.Stdin)

func nextInt() int {
	sc.Scan()
	v, _ := strconv.Atoi(sc.Text())
	return v
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	n, m := nextInt(), nextInt()
	houses := make([]int, n)
	stores := make([]int, m)
	for i := range houses {
		houses[i] = nextInt()
	}
	for i := range stores {
		stores[i] = nextInt()
	}
	sort.Ints(stores)
	for i, h := range houses {
		idx := sort.SearchInts(stores, h)
		best := -1
		if idx < m {
			best = stores[idx]
		}
		if idx > 0 {
			c := stores[idx-1]
			// Closer store wins; on a tie the smaller position wins.
			if best < 0 || abs(c-h) < abs(best-h) || (abs(c-h) == abs(best-h) && c < best) {
				best = c
			}
		}
		if i > 0 {
			out.WriteByte(' ')
		}
		out.WriteString(strconv.Itoa(best))
	}
	out.WriteByte('\n')
}
